import{_ as r,a0 as n,w as o,s as b,ao as s,I as p,x as t,a1 as i,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse(`{"title":"關於Linux防火牆'iptables'的面試問答 | LCTT x X-CMD","titleTemplate":false,"description":"關於Linux防火牆'iptables'的面試問答 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關於Linux防火牆'iptables'的面試問答 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關於Linux防火牆'iptables'的面試問答 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150604 Nishita Agarwal Shares Her Interview Experience on Linux 'iptables' Firewall","title":"關於Linux防火牆'iptables'的面試問答","tag":"201508","desc":""},"relativePath":"201508/20150604 Nishita Agarwal Shares Her Interview Experience on Linux 'iptables' Firewall.md","filePath":"[post].md"}`),d={name:"201508/20150604 Nishita Agarwal Shares Her Interview Experience on Linux 'iptables' Firewall.md"};function h(w,e,T,c,C,P){const a=n("Link");return o(),b("div",null,[e[17]||(e[17]=s('<h1 id="關於linux防火牆-iptables-的面試問答" tabindex="-1">關於Linux防火牆&#39;iptables&#39;的面試問答 <a class="header-anchor" href="#關於linux防火牆-iptables-的面試問答" aria-label="Permalink to “關於Linux防火牆&#39;iptables&#39;的面試問答”">​</a></h1><p>Nishita Agarwal是Tecmint的用户，她將分享關於她剛剛經歷的一家公司（印度的一傢俬人公司Pune）的面試經驗。在面試中她被問及許多不同的問題，但她是iptables方面的專家，因此她想分享這些關於iptables的問題和相應的答案給那些以後可能會進行相關面試的人。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Linux-iptables-Interview-Questions.jpg" alt="Linux防火牆Iptables面試問題"></p><p>所有的問題和相應的答案都基於Nishita Agarwal的記憶並經過了重寫。</p><blockquote><p>“嗨，朋友！我叫<strong>Nishita Agarwal</strong>。我已經取得了理學學士學位，我的專業集中在UNIX和它的變種（BSD，Linux）。它們一直深深的吸引着我。我在存儲方面有1年多的經驗。我正在尋求職業上的變化，並將供職於印度的Pune公司。”</p></blockquote><p>下面是我在面試中被問到的問題的集合。我已經把我記憶中有關iptables的問題和它們的答案記錄了下來。希望這會對您未來的面試有所幫助。</p><h3 id="_1-你聽説過linux下面的iptables和firewalld麼-知不知道它們是什麼-是用來幹什麼的" tabindex="-1">1. 你聽説過Linux下面的iptables和Firewalld麼？知不知道它們是什麼，是用來幹什麼的？ <a class="header-anchor" href="#_1-你聽説過linux下面的iptables和firewalld麼-知不知道它們是什麼-是用來幹什麼的" aria-label="Permalink to “1. 你聽説過Linux下面的iptables和Firewalld麼？知不知道它們是什麼，是用來幹什麼的？”">​</a></h3><p><strong>答案</strong> : iptables和Firewalld我都知道，並且我已經使用iptables好一段時間了。iptables主要由C語言寫成，並且以GNU GPL許可證發佈。它是從系統管理員的角度寫的，最新的穩定版是iptables 1.4.21。iptables通常被用作類UNIX系統中的防火牆，更準確的説，可以稱為iptables/netfilter。管理員通過終端/GUI工具與iptables打交道，來添加和定義防火牆規則到預定義的表中。Netfilter是內核中的一個模組，它執行包過濾的任務。</p><p>Firewalld是RHEL/CentOS 7（也許還有其他發行版，但我不太清楚）中最新的過濾規則的實現。它已經取代了iptables接口，並與netfilter相連接。</p><h3 id="_2-你用過一些iptables的gui或命令列工具麼" tabindex="-1">2. 你用過一些iptables的GUI或命令列工具麼？ <a class="header-anchor" href="#_2-你用過一些iptables的gui或命令列工具麼" aria-label="Permalink to “2. 你用過一些iptables的GUI或命令列工具麼？”">​</a></h3>',10)),p("p",null,[e[1]||(e[1]=p("strong",null,"答案",-1)),e[2]||(e[2]=t(" : 雖然我既用過GUI工具，比如與",-1)),i(a,{href:"http://www.tecmint.com/install-webmin-web-based-system-administration-tool-for-rhel-centos-fedora/"},{default:l(()=>[...e[0]||(e[0]=[t("Webmin",-1)])]),_:1}),e[3]||(e[3]=t("結合的Shorewall；以及直接通過終端訪問iptables，但我必須承認通過Linux終端直接訪問iptables能給予用户更高級的靈活性、以及對其背後工作更好的理解的能力。GUI適合初級管理員，而終端適合有經驗的管理員。",-1))]),e[18]||(e[18]=s(`<h3 id="_3-那麼iptables和firewalld的基本區別是什麼呢" tabindex="-1">3. 那麼iptables和firewalld的基本區別是什麼呢？ <a class="header-anchor" href="#_3-那麼iptables和firewalld的基本區別是什麼呢" aria-label="Permalink to “3. 那麼iptables和firewalld的基本區別是什麼呢？”">​</a></h3><p><strong>答案</strong> : iptables和firewalld都有着同樣的目的（包過濾），但它們使用不同的方式。iptables與firewalld不同，在每次發生更改時都刷新整個規則集。通常iptables配置文件位於‘/etc/sysconfig/iptables‘，而firewalld的配置文件位於‘/etc/firewalld/‘。firewalld的配置文件是一組XML文件。以XML為基礎進行配置的firewalld比iptables的配置更加容易，但是兩者都可以完成同樣的任務。例如，firewalld可以在自己的命令列界面以及基於XML的配置文件下使用iptables。</p><h3 id="_4-如果有機會的話-你會在你所有的服務器上用firewalld替換iptables麼" tabindex="-1">4. 如果有機會的話，你會在你所有的服務器上用firewalld替換iptables麼？ <a class="header-anchor" href="#_4-如果有機會的話-你會在你所有的服務器上用firewalld替換iptables麼" aria-label="Permalink to “4. 如果有機會的話，你會在你所有的服務器上用firewalld替換iptables麼？”">​</a></h3><p><strong>答案</strong> : 我對iptables很熟悉，它也工作的很好。如果沒有任何需求需要firewalld的動態特性，那麼沒有理由把所有的配置都從iptables移動到firewalld。通常情況下，目前為止，我還沒有看到iptables造成什麼麻煩。IT技術的通用準則也説道“為什麼要修一件沒有壞的東西呢？”。上面是我自己的想法，但如果組織願意用firewalld替換iptables的話，我不介意。</p><h3 id="_5-你看上去對iptables很有信心-巧的是-我們的服務器也在使用iptables。" tabindex="-1">5. 你看上去對iptables很有信心，巧的是，我們的服務器也在使用iptables。 <a class="header-anchor" href="#_5-你看上去對iptables很有信心-巧的是-我們的服務器也在使用iptables。" aria-label="Permalink to “5. 你看上去對iptables很有信心，巧的是，我們的服務器也在使用iptables。”">​</a></h3><p>iptables使用的表有哪些？請簡要的描述iptables使用的表以及它們所支持的鏈。</p><p><strong>答案</strong> : 謝謝您的讚賞。至於您問的問題，iptables使用的表有四個，它們是：</p><ul><li>Nat 表</li><li>Mangle 表</li><li>Filter 表</li><li>Raw 表</li></ul><p>Nat表 : Nat表主要用於網絡地址轉換。根據表中的每一條規則修改網絡包的IP地址。流中的包僅遍歷一遍Nat表。例如，如果一個通過某個接口的包被修飾（修改了IP地址），該流中其餘的包將不再遍歷這個表。通常不建議在這個表中進行過濾，由NAT表支持的鏈稱為PREROUTING 鏈，POSTROUTING 鏈和OUTPUT 鏈。</p><p>Mangle表 : 正如它的名字一樣，這個表用於校正網絡包。它用來對特殊的包進行修改。它能夠修改不同包的頭部和內容。Mangle表不能用於地址偽裝。支持的鏈包括PREROUTING 鏈，OUTPUT 鏈，Forward 鏈，Input 鏈和POSTROUTING 鏈。</p><p>Filter表 : Filter表是iptables中使用的默認表，它用來過濾網絡包。如果沒有定義任何規則，Filter表則被當作默認的表，並且基於它來過濾。支持的鏈有INPUT 鏈，OUTPUT 鏈，FORWARD 鏈。</p><p>Raw表 : Raw表在我們想要配置之前被豁免的包時被使用。它支持PREROUTING 鏈和OUTPUT 鏈。</p><h3 id="_6-簡要談談什麼是iptables中的目標值-能被指定為目標-他們有什麼用" tabindex="-1">6. 簡要談談什麼是iptables中的目標值（能被指定為目標），他們有什麼用 <a class="header-anchor" href="#_6-簡要談談什麼是iptables中的目標值-能被指定為目標-他們有什麼用" aria-label="Permalink to “6. 簡要談談什麼是iptables中的目標值（能被指定為目標），他們有什麼用”">​</a></h3><p><strong>答案</strong> : 下面是在iptables中可以指定為目標的值：</p><ul><li>ACCEPT : 接受包</li><li>QUEUE : 將包傳遞到用户空間 (應用程序和驅動所在的地方)</li><li>DROP : 丟棄包</li><li>RETURN : 將控制權交回調用的鏈並且為當前鏈中的包停止執行下一調用規則</li></ul><h3 id="_7-讓我們來談談iptables技術方面的東西-我的意思是説實際使用方面" tabindex="-1">7. 讓我們來談談iptables技術方面的東西，我的意思是説實際使用方面 <a class="header-anchor" href="#_7-讓我們來談談iptables技術方面的東西-我的意思是説實際使用方面" aria-label="Permalink to “7. 讓我們來談談iptables技術方面的東西，我的意思是説實際使用方面”">​</a></h3><p>你怎麼檢測在CentOS中安裝iptables時需要的iptables的rpm？</p><p><strong>答案</strong> : iptables已經被默認安裝在CentOS中，我們不需要單獨安裝它。但可以這樣檢測rpm：</p><pre><code># rpm -qa iptables

iptables-1.4.21-13.el7.x86_64
</code></pre><p>如果您需要安裝它，您可以用yum來安裝。</p><pre><code># yum install iptables-services
</code></pre><h3 id="_8-怎樣檢測並且確保iptables服務正在運行" tabindex="-1">8. 怎樣檢測並且確保iptables服務正在運行？ <a class="header-anchor" href="#_8-怎樣檢測並且確保iptables服務正在運行" aria-label="Permalink to “8. 怎樣檢測並且確保iptables服務正在運行？”">​</a></h3><p><strong>答案</strong> : 您可以在終端中運行下面的命令來檢測iptables的狀態。</p><pre><code># service status iptables			[On CentOS 6/5]
# systemctl status iptables			[On CentOS 7]
</code></pre><p>如果iptables沒有在運行，可以使用下面的語句</p><pre><code>---------------- 在CentOS 6/5下 ---------------- 
# chkconfig --level 35 iptables on
# service iptables start

---------------- 在CentOS 7下 ---------------- 
# systemctl enable iptables 
# systemctl start iptables 
</code></pre><p>我們還可以檢測iptables的模組是否被加載：</p><pre><code># lsmod | grep ip_tables
</code></pre><h3 id="_9-你怎麼檢查iptables中當前定義的規則呢" tabindex="-1">9. 你怎麼檢查iptables中當前定義的規則呢？ <a class="header-anchor" href="#_9-你怎麼檢查iptables中當前定義的規則呢" aria-label="Permalink to “9. 你怎麼檢查iptables中當前定義的規則呢？”">​</a></h3><p><strong>答案</strong> : 當前的規則可以簡單的用下面的命令查看：</p><pre><code># iptables -L
</code></pre><p>示例輸出</p><pre><code>Chain INPUT (policy ACCEPT)
target     prot opt source               destination         
ACCEPT     all  --  anywhere             anywhere             state RELATED,ESTABLISHED
ACCEPT     icmp --  anywhere             anywhere            
ACCEPT     all  --  anywhere             anywhere            
ACCEPT     tcp  --  anywhere             anywhere             state NEW tcp dpt:ssh
REJECT     all  --  anywhere             anywhere             reject-with icmp-host-prohibited

Chain FORWARD (policy ACCEPT)
target     prot opt source               destination         
REJECT     all  --  anywhere             anywhere             reject-with icmp-host-prohibited

Chain OUTPUT (policy ACCEPT)
target     prot opt source               destination
</code></pre><h3 id="_10-你怎樣刷新所有的iptables規則或者特定的鏈呢" tabindex="-1">10. 你怎樣刷新所有的iptables規則或者特定的鏈呢？ <a class="header-anchor" href="#_10-你怎樣刷新所有的iptables規則或者特定的鏈呢" aria-label="Permalink to “10. 你怎樣刷新所有的iptables規則或者特定的鏈呢？”">​</a></h3><p><strong>答案</strong> : 您可以使用下面的命令來刷新一個特定的鏈。</p><pre><code># iptables --flush OUTPUT
</code></pre><p>要刷新所有的規則，可以用：</p><pre><code># iptables --flush
</code></pre><h3 id="_11-請在iptables中添加一條規則-接受所有從一個信任的ip地址-例如-192-168-0-7-過來的包。" tabindex="-1">11. 請在iptables中添加一條規則，接受所有從一個信任的IP地址（例如，192.168.0.7）過來的包。 <a class="header-anchor" href="#_11-請在iptables中添加一條規則-接受所有從一個信任的ip地址-例如-192-168-0-7-過來的包。" aria-label="Permalink to “11. 請在iptables中添加一條規則，接受所有從一個信任的IP地址（例如，192.168.0.7）過來的包。”">​</a></h3><p><strong>答案</strong> : 上面的場景可以通過運行下面的命令來完成。</p><pre><code># iptables -A INPUT -s 192.168.0.7 -j ACCEPT 
</code></pre><p>我們還可以在源IP中使用標準的斜線和子網掩碼：</p><pre><code># iptables -A INPUT -s 192.168.0.7/24 -j ACCEPT 
# iptables -A INPUT -s 192.168.0.7/255.255.255.0 -j ACCEPT
</code></pre><h3 id="_12-怎樣在iptables中添加規則以accept-reject-deny和drop-ssh的服務" tabindex="-1">12. 怎樣在iptables中添加規則以ACCEPT，REJECT，DENY和DROP ssh的服務？ <a class="header-anchor" href="#_12-怎樣在iptables中添加規則以accept-reject-deny和drop-ssh的服務" aria-label="Permalink to “12. 怎樣在iptables中添加規則以ACCEPT，REJECT，DENY和DROP ssh的服務？”">​</a></h3><p><strong>答案</strong> : 但願ssh運行在22端口，那也是ssh的默認端口，我們可以在iptables中添加規則來ACCEPT ssh的tcp包（在22號端口上）。</p><pre><code># iptables -A INPUT -s -p tcp --dport 22 -j ACCEPT 
</code></pre><p>REJECT ssh服務（22號端口）的tcp包。</p><pre><code># iptables -A INPUT -s -p tcp --dport 22 -j REJECT
</code></pre><p>DENY ssh服務（22號端口）的tcp包。</p><pre><code># iptables -A INPUT -s -p tcp --dport 22 -j DENY
</code></pre><p>DROP ssh服務（22號端口）的tcp包。</p><pre><code># iptables -A INPUT -s -p tcp --dport 22 -j DROP
</code></pre><h3 id="_13-讓我給你另一個場景-假如有一台電腦的本地ip地址是192-168-0-6。你需要封鎖在21、22、23和80號端口上的連接-你會怎麼做" tabindex="-1">13. 讓我給你另一個場景，假如有一台電腦的本地IP地址是192.168.0.6。你需要封鎖在21、22、23和80號端口上的連接，你會怎麼做？ <a class="header-anchor" href="#_13-讓我給你另一個場景-假如有一台電腦的本地ip地址是192-168-0-6。你需要封鎖在21、22、23和80號端口上的連接-你會怎麼做" aria-label="Permalink to “13. 讓我給你另一個場景，假如有一台電腦的本地IP地址是192.168.0.6。你需要封鎖在21、22、23和80號端口上的連接，你會怎麼做？”">​</a></h3><p><strong>答案</strong> : 這時，我所需要的就是在iptables中使用‘multiport‘選項，並將要封鎖的端口號跟在它後面。上面的場景可以用下面的一條語句搞定：</p><pre><code># iptables -A INPUT -s 192.168.0.6 -p tcp -m multiport --dport 22,23,80,8080 -j DROP
</code></pre><p>可以用下面的語句查看寫入的規則。</p><pre><code># iptables -L

Chain INPUT (policy ACCEPT)
target     prot opt source               destination         
ACCEPT     all  --  anywhere             anywhere             state RELATED,ESTABLISHED
ACCEPT     icmp --  anywhere             anywhere            
ACCEPT     all  --  anywhere             anywhere            
ACCEPT     tcp  --  anywhere             anywhere             state NEW tcp dpt:ssh
REJECT     all  --  anywhere             anywhere             reject-with icmp-host-prohibited
DROP       tcp  --  192.168.0.6          anywhere             multiport dports ssh,telnet,http,webcache

Chain FORWARD (policy ACCEPT)
target     prot opt source               destination         
REJECT     all  --  anywhere             anywhere             reject-with icmp-host-prohibited

Chain OUTPUT (policy ACCEPT)
target     prot opt source               destination
</code></pre><p><strong>面試官</strong> : 好了，我問的就是這些。你是一個很有價值的僱員，我們不會錯過你的。我將會向HR推薦你的名字。如果你有什麼問題，請問我。</p><p>作為一個候選人我不願不斷的問將來要做的項目的事以及公司裏其他的事，這樣會打斷愉快的對話。更不用説HR輪會不會比較難，總之，我獲得了機會。</p><p>同時我要感謝Avishek和Ravi（我的朋友）花時間幫我整理我的面試。</p><p>朋友！如果您有過類似的面試，並且願意與數百萬Tecmint讀者一起分享您的面試經歷，請將您的問題和答案發送到admin@tecmint.com。</p><p>謝謝！保持聯繫。如果我能更好的回答我上面的問題的話，請記得告訴我。</p><hr>`,63)),p("p",null,[e[5]||(e[5]=t("via: ",-1)),i(a,{href:"http://www.tecmint.com/linux-firewall-iptables-interview-questions-and-answers/"},{default:l(()=>[...e[4]||(e[4]=[t("http://www.tecmint.com/linux-firewall-iptables-interview-questions-and-answers/",-1)])]),_:1})]),p("p",null,[e[9]||(e[9]=t("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/avishek/"},{default:l(()=>[...e[6]||(e[6]=[t("Avishek Kumar",-1)])]),_:1}),e[10]||(e[10]=t(" 譯者：",-1)),i(a,{href:"https://github.com/wwy-hust"},{default:l(()=>[...e[7]||(e[7]=[t("wwy-hust",-1)])]),_:1}),e[11]||(e[11]=t(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:l(()=>[...e[8]||(e[8]=[t("wxy",-1)])]),_:1})]),p("p",null,[e[14]||(e[14]=t("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[12]||(e[12]=[t("LCTT",-1)])]),_:1}),e[15]||(e[15]=t(" 原創翻譯，",-1)),i(a,{href:"https://linux.cn/"},{default:l(()=>[...e[13]||(e[13]=[t("Linux中國",-1)])]),_:1}),e[16]||(e[16]=t(" 榮譽推出",-1))])])}const E=r(d,[["render",h]]);export{f as __pageData,E as default};
